VfsFixture::CmdSeqResult VfsFixture::run( const std::string & cmd_sequence )
{
	CmdSeqResult result;

	auto pieces = Tools::split_string_view( cmd_sequence, ";" );
	for( auto & raw : pieces ) {
		auto trimmed = Tools::strip( std::string( raw ) );
		if( trimmed.empty() ) {
			continue;
		}

		auto r = parser->execute_command_string( trimmed );
		result.output += r.output;
		if( !r.success ) {
			result.all_ok     = false;
			result.last_error = r.message;
			CPPDEBUG( Tools::format(
				"VfsFixture: command '%s' failed: %s", trimmed, r.message ) );
		}
		if( r.stop_execution ) {
			break;
		}
	}

	return result;
}

