// AI generated by GitHub Copilot Claude Opus 4.7 START
DriveInspect inspect_drive( const VfsFixture & fix,
                            const std::string & drive_name,
                            bool                pull_contents )
{
	DriveInspect info;

	std::string bin_path;
	if( drive_name == "a" ) {
		bin_path = fix.drive_a_path;
	} else if( drive_name == "b" ) {
		bin_path = fix.drive_b_path;
	} else {
		CPPDEBUG( Tools::format( "inspect_drive: unknown drive %s", drive_name ) );
		return info;
	}

	if( !std::filesystem::exists( bin_path ) ) {
		CPPDEBUG( Tools::format( "inspect_drive: missing bin file %s", bin_path ) );
		return info;
	}

	// The VFS server still owns the file handle on this bin file
	// (the simulator keeps the fstream open). The dynamic FS opens
	// its own independent fstream over the same path though - reads
	// see whatever was last flushed by the simulator. Every command
	// in this fixture's path either closes the handle (file goes
	// out of scope on command exit) or calls flush() before
	// returning, so we observe the on-disk state at command-sequence
	// completion.
	SimFlashFsFlashMemory inspect_mem( bin_path );
	::SimpleFlashFs::dynamic::SimpleFlashFsReadOnly inspect_fs( &inspect_mem );

	if( !inspect_fs.init() ) {
		CPPDEBUG( Tools::format( "inspect_drive: init failed on %s", bin_path ) );
		return info;
	}

	info.mounted         = true;
	info.free_data_pages = inspect_fs.get_number_of_free_data_pages();

	// Dedup by inode_number, keeping the highest inode_version_number
	// (COW leaves older versions on disk until lazy erase).
	// An inode whose latest version has an empty file_name is the
	// tombstone of a deleted file and is omitted.
	struct LatestEntry {
		std::shared_ptr<::SimpleFlashFs::dynamic::SimpleFlashFs::FileHandle> handle;
		uint64_t version = 0;
	};
	std::map<uint64_t, LatestEntry> latest_by_inode;

	for( auto inode : inspect_fs.get_all_inodes( false ) ) {
		if( !inode ) {
			continue;
		}
		uint64_t inum = inode->inode.inode_number;
		auto     it   = latest_by_inode.find( inum );
		if( it == latest_by_inode.end() ||
		    inode->inode.inode_version_number > it->second.version ) {
			latest_by_inode[inum] = { inode,
			                          inode->inode.inode_version_number };
		}
	}

	for( auto & [inum, entry] : latest_by_inode ) {
		if( entry.handle->inode.file_name.empty() ) {
			continue; // deleted file
		}
		DriveInspect::InodeView v;
		v.file_name        = entry.handle->inode.file_name;
		v.file_len         = entry.handle->inode.file_len;
		v.data_pages_count = entry.handle->inode.data_pages.size();
		v.inode_data_size  = entry.handle->inode.inode_data.size();
		v.inode_number     = entry.handle->inode.inode_number;
		v.inode_version    = entry.handle->inode.inode_version_number;
		v.page             = entry.handle->page;

		if( pull_contents && v.file_len > 0 ) {
			v.contents.resize( v.file_len );
			entry.handle->seek( 0 );
			std::size_t bytes_read =
				entry.handle->read( v.contents.data(), v.contents.size() );
			v.contents.resize( bytes_read );
		}

		info.inodes.push_back( std::move( v ) );
	}

	return info;
}

const DriveInspect::InodeView * find_file( const DriveInspect & info,
                                           const std::string_view & name )
{
	for( const auto & v : info.inodes ) {
		if( v.file_name == name ) {
			return &v;
		}
	}
	return nullptr;
}

bool bytes_equal( const std::vector<std::byte> & got,
                  const std::string_view &       expected,
                  const char *                   label )
{
	if( got.size() != expected.size() ) {
		CPPDEBUG( Tools::format( "%s: size mismatch got=%d expected=%d",
		                         label, got.size(), expected.size() ) );
		return false;
	}
	for( std::size_t i = 0; i < got.size(); i++ ) {
		if( static_cast<char>( got[i] ) != expected[i] ) {
			CPPDEBUG( Tools::format(
				"%s: byte mismatch at i=%d got=0x%02X expected=0x%02X",
				label, i, static_cast<unsigned>( got[i] ),
				static_cast<unsigned>( static_cast<unsigned char>( expected[i] ) ) ) );
			return false;
		}
	}
	return true;
}
